class TextClust:
    def track_normalized_mutual_info(self):
        return self._run()

    def setup(self):
        self.dataset = datasets.NewsT()
        self.model = (
            _extract_text
            | feature_extraction.BagOfWords()
            | cluster.TextClust(
                fading_factor=0.01,
                tgap=200,
                real_time_fading=False,
                min_weight=1,
                auto_r=True,
                sigma=0.5,
            )
        )

